export type Kind = 'object' | 'character' | 'text';
export type Rect = { x: number; y: number; w: number; h: number };
export type Region = Rect & { id: string; kind: Kind; text: string; description: string; colors: string[]; tags: string[]; locked?: boolean };
export type LayoutState = { caption: string; meta: string[]; canvas: string; palette: string[]; regions: Region[] };
export type Size = { width: number; height: number };
export type Starter = { id: string; name: string; hint: string; canvas: string; meta: string[]; caption: string; items: Array<[Kind, number, number, number, number, string, string?]> };
export type Imported = { summary_caption?: string; meta?: string; canvas?: string; palette?: string; regions?: Array<Partial<Region>>; width?: number; height?: number; warnings?: string[] };
export type Guide = { axis: 'x' | 'y'; at: number };
export type GridItem = { label: string; caption: string; bbox: [number, number, number, number]; text?: string };

export const KINDS: Array<{ value: Kind; label: string }>;
export const CANVASES: Array<{ value: string; label: string }>;
export const META_SUGGESTIONS: string[];
export const PLACES: Array<{ value: string; label: string; rect: Rect }>;
export const STARTERS: Starter[];
export const SNAP_PX: number;
export function clamp(value: number, low: number, high: number): number;
export function uid(): string;
export function splitList(text: string): string[];
export function pad2(value: number): string;
export function emptyState(): LayoutState;
export function newRegion(kind: Kind, rect: Rect): Region;
export function starterState(starter: Starter, caption?: string): LayoutState;
export function layoutPayload(state: LayoutState, size: Size, format?: 'compact' | 'pretty'): Record<string, string | number>;
export function stateFromImport(imported: Imported): LayoutState;
export function foreignKind(value: unknown): 'assistant' | null;
export function layoutInfo(text: string): { items: number; text: number } | null;
export function findLayout(value: unknown, depth?: number): string | null;
export function inferSourceSize(text: string, size: Size): Size | null;
export function normalizeLayout(text: string): { text: string; size: Size | null; locks: boolean[] };
export function regionsToGrid(regions: Region[]): GridItem[];
export function gridRect(bbox: number[]): Rect;
export function overlap(a: Rect, b: Rect): number;
export function keepLocked(previous: Region[], next: Region[]): Region[];
export function carryColours(previous: Region[], next: Region[]): Region[];
export function ocrLines(words: Array<{ label: string; bbox: number[] }>, size: Size, limit?: number): Array<{ text: string; bbox: number[] }>;
export function issueFromError(message: string): { number: number | null; need: 'caption' | 'text' | null; text: string };
export function fitRect(image: Size, fit: 'cover' | 'contain', out: Size): Rect;
export function snapLines(regions: Region[], id: string, thirds?: boolean): { x: number[]; y: number[] };
export function snapAxis(points: number[], lines: number[], pixels: number): { delta: number; line: number } | null;
export function dragRect(input: { mode: string; start: Rect; origin: { x: number; y: number }; point: { x: number; y: number }; size: Size; lines?: { x: number[]; y: number[] } | null; board?: Size | null }): { rect: Rect; guides: Guide[] };
export function clipboardFile(data: DataTransfer | null | undefined): File | null;
export function pngTexts(buffer: ArrayBuffer): Promise<string[]>;
export function fingerprint(text: string): string;
